import { spawn } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";

const root = process.cwd();
const configPath = process.env.HARNESS_CONFIG ?? "harness.config.json";
const config = JSON.parse(readFileSync(configPath, "utf8"));
const criterion = config.criteria.find((entry) => entry.id === "escape-hatches");
const probe = path.join(root, criterion.check.rules[0].path);

const child = spawn(
  "node",
  ["scripts/harness-score.mjs", "--only", "escape-hatches"],
  { cwd: root, stdio: ["ignore", "pipe", "pipe"] },
);

const deadline = Date.now() + 60000;
while (!existsSync(probe) && Date.now() < deadline) {
  await new Promise((resolve) => setTimeout(resolve, 20));
}

if (!existsSync(probe)) {
  console.error("the probe file never appeared, the test proves nothing");
  process.exit(1);
}

child.kill("SIGTERM");
await new Promise((resolve) => child.on("close", resolve));

if (existsSync(probe)) {
  console.error("the probe file survived the signal");
  process.exit(1);
}

console.log("the tree is clean after the signal");

import { spawn } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";

const root = process.cwd();
const configPath = process.env.HARNESS_CONFIG ?? "harness.config.json";
const config = JSON.parse(readFileSync(configPath, "utf8"));
const criterion = config.criteria.find((entry) => entry.id === "escape-hatches");
const probe = path.join(root, criterion.check.rules[0].path);

const child = spawn(
  "node",
  ["scripts/harness-score.mjs", "--only", "escape-hatches"],
  { cwd: root, stdio: ["ignore", "pipe", "pipe"] },
);

const deadline = Date.now() + 60000;
while (!existsSync(probe) && Date.now() < deadline) {
  await new Promise((resolve) => setTimeout(resolve, 20));
}

if (!existsSync(probe)) {
  console.error("the probe file never appeared, the test proves nothing");
  process.exit(1);
}

child.kill("SIGKILL");
await new Promise((resolve) => child.on("close", resolve));

if (!existsSync(probe)) {
  console.error("the killed run left no probe file, the test proves nothing");
  process.exit(1);
}

const repair = spawn(
  "node",
  ["scripts/harness-score.mjs", "--only", "escape-hatches"],
  { cwd: root, stdio: ["ignore", "pipe", "pipe"] },
);
let output = "";
repair.stdout.on("data", (chunk) => {
  output += chunk;
});
repair.stderr.on("data", (chunk) => {
  output += chunk;
});
const code = await new Promise((resolve) => repair.on("close", resolve));

if (existsSync(probe)) {
  console.error("the tree is still dirty after the repair run");
  process.exit(1);
}
if (code !== 0) {
  console.error("the repair run failed:\n" + output);
  process.exit(1);
}

console.log("the tree is clean after the repair run");
